with filtered as (select id, order_id, shipped_date, delivered_date, cost, coalesce(cost, 0) as cost_filled from shipments where order_id is not null), ranked as (select *, row_number() over (partition by order_id order by shipped_date, id) as latest_rank from filtered qualify latest_rank = 1), with_dims as (select e.id, e.order_id, e.shipped_date, e.cost, o.amount from ranked e left join orders o on e.order_id = o.id where o.channel != 'store'), matched_keys as (select id from with_dims intersect all select id from shipments where year(delivered_date) >= 2023), reconciled as (select s.* from with_dims s inner join matched_keys k on s.id = k.id) select id, order_id, cost, amount from reconciled order by cost desc nulls first, amount;
